// Title-case a building-style name for display (designs store either the label
// "Farmland" or the lowercase key "cabin").
function capWords(s) { return String(s || "").replace(/\b\w/g, (c) => c.toUpperCase()); }

// Board-and-batten door glyph for the palette buttons (single + double), modeled on the
// real shed doors: cream frame, vertical planks, a mid cross-rail, black T-hinges, and a
// latch. Replaces the generic door emoji so the button reads as the actual product.
function DoorIcon({ double = false }) {
  const FRAME = "#ECE4D3", PANEL = "#B99A82", PLANK = "#8B7058", IRON = "#2C2A28";
  const leaf = (x, w, hingeLeft) => {
    const planks = [];
    for (let i = 1; i <= 3; i++) { const px = x + (w * i) / 4; planks.push(<line key={i} x1={px} y1={2.6} x2={px} y2={15.4} stroke={PLANK} strokeWidth={0.4} />); }
    const hx = hingeLeft ? x + 0.5 : x + w - 1.8;
    return (
      <g key={x}>
        <rect x={x} y={1} width={w} height={16} rx={0.5} fill={FRAME} stroke="#B5A98E" strokeWidth={0.7} />
        <rect x={x + 1.1} y={2.2} width={w - 2.2} height={13.6} fill={PANEL} />
        {planks}
        <rect x={x + 1.1} y={8.1} width={w - 2.2} height={1.2} fill={FRAME} />
        <rect x={hx} y={3.4} width={1.3} height={0.9} fill={IRON} />
        <rect x={hx} y={12.8} width={1.3} height={0.9} fill={IRON} />
      </g>
    );
  };
  if (double) {
    return (
      <svg width={18} height={16} viewBox="0 0 20 18" style={{ display: "block" }} aria-hidden="true">
        {leaf(0.5, 9, true)}
        {leaf(10.5, 9, false)}
        <rect x={9.2} y={8.3} width={1.6} height={0.9} fill={IRON} />
      </svg>
    );
  }
  return (
    <svg width={11} height={16} viewBox="0 0 12 18" style={{ display: "block" }} aria-hidden="true">
      {leaf(0.5, 11, true)}
      <rect x={9.4} y={8.2} width={1.4} height={0.9} fill={IRON} />
    </svg>
  );
}

// Closest point distance from (px,py) to the segment (x1,y1)-(x2,y2)
function _distToSeg(px, py, x1, y1, x2, y2) {
  const dx = x2 - x1, dy = y2 - y1;
  const lenSq = dx * dx + dy * dy;
  let t = lenSq ? ((px - x1) * dx + (py - y1) * dy) / lenSq : 0;
  t = Math.max(0, Math.min(1, t));
  const cx = x1 + t * dx, cy = y1 + t * dy;
  return Math.sqrt((px - cx) * (px - cx) + (py - cy) * (py - cy));
}

// Treat each wall as a line segment; pick the wall closest to the click.
// Returns null only when the click is too far from any wall to be reasonable.
function getWallFromClick(x, y, pW, pH, mgX, mgY) {
  const ix = x - mgX, iy = y - mgY, T = 80;
  const walls = [
    { wall: "north", d: _distToSeg(ix, iy, 0, 0, pW, 0) },
    { wall: "south", d: _distToSeg(ix, iy, 0, pH, pW, pH) },
    { wall: "west",  d: _distToSeg(ix, iy, 0, 0, 0, pH) },
    { wall: "east",  d: _distToSeg(ix, iy, pW, 0, pW, pH) },
  ];
  walls.sort((a, b) => a.d - b.d);
  return walls[0].d <= T ? walls[0].wall : null;
}

function snapToWall(wall, cx, cy, iW, iH, pW, pH, mgX, mgY) {
  const hw = iW / 2;
  switch (wall) {
    case "north": return { x: Math.max(mgX + hw, Math.min(cx, mgX + pW - hw)), y: mgY, rotation: 0, wall };
    case "south": return { x: Math.max(mgX + hw, Math.min(cx, mgX + pW - hw)), y: mgY + pH, rotation: 0, wall };
    case "west":  return { x: mgX, y: Math.max(mgY + hw, Math.min(cy, mgY + pH - hw)), rotation: 90, wall };
    case "east":  return { x: mgX + pW, y: Math.max(mgY + hw, Math.min(cy, mgY + pH - hw)), rotation: 90, wall };
    default: return { x: cx, y: cy, rotation: 0, wall: null };
  }
}

function snapToWallInterior(wall, cx, cy, iW, iH, pW, pH, mgX, mgY) {
  switch (wall) {
    case "north": return { x: Math.max(mgX + iW / 2, Math.min(cx, mgX + pW - iW / 2)), y: mgY + iH / 2, rotation: 0, wall };
    case "south": return { x: Math.max(mgX + iW / 2, Math.min(cx, mgX + pW - iW / 2)), y: mgY + pH - iH / 2, rotation: 0, wall };
    case "west":  return { x: mgX + iH / 2, y: Math.max(mgY + iW / 2, Math.min(cy, mgY + pH - iW / 2)), rotation: 90, wall };
    case "east":  return { x: mgX + pW - iH / 2, y: Math.max(mgY + iW / 2, Math.min(cy, mgY + pH - iW / 2)), rotation: 90, wall };
    default: return { x: cx, y: cy, rotation: 0, wall: null };
  }
}

// Always returns a wall — used as a fallback when the click is ambiguous or far
// from the plan. Uses segment distance so corner clicks resolve to the closer side.
function getNearestWall(x, y, pW, pH, mgX, mgY) {
  const ix = x - mgX, iy = y - mgY;
  const walls = [
    { wall: "north", d: _distToSeg(ix, iy, 0, 0, pW, 0) },
    { wall: "south", d: _distToSeg(ix, iy, 0, pH, pW, pH) },
    { wall: "west",  d: _distToSeg(ix, iy, 0, 0, 0, pH) },
    { wall: "east",  d: _distToSeg(ix, iy, pW, 0, pW, pH) },
  ];
  walls.sort((a, b) => a.d - b.d);
  return walls[0].wall;
}

// ⚠️ REWRITTEN 2026-09-04 FOR THE LOFT DOOR, and the rule it replaced is written out here
// rather than deleted, because it was RIGHT for as long as every door stood on the floor. It
// was: "Only check doors on the same wall" — an overlap along the wall axis and nothing
// else. With one plane to share, two bars that overlap in plan really are in each other's
// way, so a purely 2D test was not an approximation; it was the whole truth.
//
// The loft door breaks that (Carolyn 2026-09-04 — see doorSillStamps). It sits high on a
// gable end, and the arrangement builders actually put on a barn is a loft door DIRECTLY
// ABOVE the walk door: same wall, same span, exactly the overlap the old rule refused. So it
// would have made the feature unusable on the one wall it exists for, and it would have done
// it with a toast that says nothing is wrong.
//
// The root cause was never the pad or the type list — it is that A PLAN VIEW HAS NO UP. The
// fix is therefore to ask for the missing axis, not to weaken the horizontal one: two
// openings clash when they overlap ALONG the wall AND their vertical bands overlap.
// ssItemVBand is that band, and it is the same one the wall elevation prints, so a refusal
// and the drawing beside it can never disagree about what is where.
//
// ⚠️ AN UNKNOWN BAND STILL REFUSES. ssItemVBand returns null when nothing on an item says
// where it sits vertically, and null has to keep meaning "assume they clash" — the old
// answer — never "let it through". Widening a placement rule on missing data is how a
// legal-looking plan reaches a shop floor.
//
// The CANDIDATE's band is read with itemTypes[ni.type], not with `nc`: most callers pass a
// bare { width: wFt } as nc, which carries no wallOnly flag, and reading the band off that
// would return null for every door and quietly restore the old behaviour everywhere.
function checkDoorCollision(ni, nc, existing, itemTypes, sc, wallHeightFt) {
  if (!ni.wall) return false;
  const niw = (ni.widthFt || nc.width) * sc;
  // `wallHeightFt` is OPTIONAL, and only a vent's band reads it (ssVentSpan measures a vent's top
  // spot down from the plate). It used to be left out on the theory that the 8 ft default puts a
  // vent lower than a taller wall would, so a 10 ft tenant "errs toward refusing". That held only
  // for a vent at the top spot. Once a vent could be moved down the wall (2026-09-15), its band was
  // CLAMPED to the 8 ft plate while the 3D drew it against the real one. The review on 09-15 pressed
  // ▲ on a 10 ft wall and ran a vent straight into a window with no refusal. So every path that moves
  // a vent passes the plate it moves the vent against; a caller that omits it keeps the old default.
  const niBand = ssItemVBand(ni, itemTypes[ni.type] || nc, itemTypes, wallHeightFt);
  // ⚠️ A GABLE VENT IS ABOVE THE PLATE, and most callers do not say where the plate is (see the
  // wallHeightFt note above). Its band is H + rise, so against an 8 ft default a vent in a 10 ft
  // building's gable would "overlap" a window at 8'4" that is really 2 ft below the plate. So a
  // gable vent meets only other gable vents, along the wall alone — two in one gable at one spot is
  // the one clash that can happen up there — and never a door, window, shelf or wall vent below it,
  // which the plate is between.
  //
  // ⚠️ That rule trusts the ventZone KEY, so the key must match the drawing. A style change that
  // takes the gable away (a single slant, a lower pitch) runs ssRefitGableVents, which brings such a
  // vent down to the wall. Before that existed a stale "gable" key let a window be placed right on
  // top of a vent the 3D drew on the wall (review, 2026-09-15).
  const niGable = ssIsGableVent(ni);
  for (const it of existing) {
    const c = itemTypes[it.type];
    // ⛔ THE `it.type === "window"` CARVE-OUT IS GONE (2026-09-10, Ahsan's decision after the
    // 09-08 call left the question open). It skipped every existing WINDOW, so this guard ran
    // in one direction only and the ORDER OF CLICKS decided whether the app protected you:
    //
    //     window THEN door -> both placed, overlapping
    //     door THEN window -> refused
    //
    // The product gave both answers to the same question, which is worse than either answer.
    // It also let two identical windows sit perfectly coincident, both priced.
    //
    // What replaces it is not a policy but a MEASUREMENT: the vertical-band test below already
    // decides this correctly, and since 2026-09-09 it reads a catalog fixture's own heightIn
    // rather than a generic default, so the numbers are finally worth trusting. A transom above
    // a door is normal construction and now places; a window driven through a door does not.
    // Flush still passes (<=, not <) — a loft door sharing a header with the opening below it
    // is how they are built.
    if (!c || !c.wallOnly) continue;
    // Same wall, or they can never touch.
    if (it.wall !== ni.wall) continue;
    // One in the gable and one below the plate never meet (see niGable above).
    const itGable = ssIsGableVent(it);
    if (itGable !== niGable) continue;
    const iw = (it.widthFt || c.width) * sc;
    const along = (ni.wall === "north" || ni.wall === "south")
      ? Math.abs(ni.x - it.x) < (niw / 2) + (iw / 2) + 4
      : Math.abs(ni.y - it.y) < (niw / 2) + (iw / 2) + 4;
    if (!along) continue;
    if (niGable) return true;   // both in the gable: along is the whole test
    // Flush is allowed (<=, not <): a loft door whose sill sits exactly on the walk door's
    // head is one framed opening over another sharing a header, which is how they are built.
    const itBand = ssItemVBand(it, c, itemTypes, wallHeightFt);
    if (niBand && itBand && (niBand.topFt <= itBand.bottomFt || itBand.topFt <= niBand.bottomFt)) continue;
    return true;
  }
  return false;
}

// Wall SLABS — the workbench family: items that own a span of wall and stop other things
// sharing it. `wallSnap` alone is not the test, because electrical devices are wallSnap too
// and must not block a door; `modelKey` is the discriminator. Its ABSENCE means a config
// predating it, where wallSnap meant workbench and nothing else — so a tenant whose config
// row has not been regenerated keeps the old rule rather than silently losing it.
const SS_SLAB_BANDS = {
  wallBench: (h) => [0, h],
  wallShelf: (h) => [h, h + 2],
  // The gap between the two boards IS the height off the floor. Carolyn declined a second
  // field for it (2026-09-01): "let's just program it right now in the 3D to be whatever the
  // height is off the floor is also the height between the next shelf. If that doesn't work
  // for people, then we will change it." So the top board sits at 2h and the band ends a
  // board's thickness above it, the same allowance the single carries.
  // This MUST track the geometry below. It was a flat h+20 for a hard-coded 16in gap, and a
  // band that no longer matches what is drawn fails in both directions at once: two doubles
  // at one height stop refusing each other, and a legal placement starts being refused.
  wallShelfDouble: (h) => [h, 2 * h + 2],
};
function ssSlabModel(type, itemTypes) {
  const c = itemTypes && itemTypes[type];
  if (!c || !c.wallSnap) return null;
  if (!c.modelKey) return "legacy";
  return SS_SLAB_BANDS[c.modelKey] ? c.modelKey : null;
}
// The inches-off-floor band an item occupies on its wall. A workbench stands on the floor and
// blocks everything under its top; a shelf is mounted and blocks only its own board(s), which
// is what lets a shelf hang above a bench. A legacy slab blocks the full height — today's
// behaviour exactly, so nothing changes for a tenant until their config carries modelKey.
function ssSlabBand(it, itemTypes) {
  const model = ssSlabModel(it.type, itemTypes);
  if (!model) return null;
  if (model === "legacy") return [0, 1e4];
  const c = itemTypes[it.type];
  const h = Number(it.heightOffFloorIn != null ? it.heightOffFloorIn : c.heightOffFloorIn) || 0;
  return SS_SLAB_BANDS[model](h);
}
function ssBandsOverlap(a, b) { return !!a && !!b && a[0] < b[1] && b[0] < a[1]; }

// How deep a wall-mounted item actually sits on the plan, in feet.
//
// THE BUILDER'S depthIn IS WHAT GETS DRAWN, so it is also what must be SNAPPED against.
// Passing the config's own `height` to snapToWallInterior while drawing depthIn is what put
// every slab half outside its wall — and straight through it in 3D, since the 3D model reads
// the same x/y. It only showed once a builder set a depth bigger than the type's default
// (Carolyn: 24 in shelves on a 1 ft default, a 36 in bench on a 2 ft one), which is why it
// survived the first round of testing.
//
// An EXISTING item wins with its own snapshotted heightFt: re-pricing a shelf's depth must
// never move one already on somebody's plan.
function slabDepthFt(cfg, it) {
  const own = it && it.heightFt != null ? Number(it.heightFt) : null;
  if (own > 0) return own;
  const d = cfg && cfg.depthIn != null ? Number(cfg.depthIn) / 12 : null;
  if (d > 0) return d;
  return (cfg && Number(cfg.height)) || 2;
}

// Does an item at `sn` overlap a wall slab on the same wall? checkDoorCollision above
// deliberately only compares wallOnly items to each other, and a slab is wallSnap, so it is
// skipped there — which meant the invariant was enforced in one direction only: dragging a
// workbench into a door showed "A door is blocking this wall!", while dragging the DOOR onto
// the workbench silently succeeded and produced exactly the layout that toast exists to
// prevent, rasterized into the PDF and sent to the shop. `cand` is the placing item when the
// caller is itself a slab; a wallOnly caller passes nothing and blocks the full height.
// EVERY DRAG REFUSAL SAYS WHY. Carolyn, 2026-09-07 12:13, dragging a window that would not
// go: "Look, I just clicked, and that window just bang went back here. Now I don't. I
// clicked, and it's gone. I don't even know where it went."
//
// She was right that nothing was wrong with the placement rules there — the item WAS being
// refused, correctly. What was missing is that a refused DRAG was a bare `return`, while
// every click-to-place path already called setToast/flash3. So a legal-but-blocked move and
// a dropped click looked identical, which is why the real placement bugs below went
// unreportable for weeks: she could not tell a refusal from a glitch.
//
// One wording per reason, shared by both the 2D and the 3D drag, so the same illegal move is
// never explained two different ways.
const SS_REFUSE_WALL = "Something else is already on that part of the wall.";
const SS_REFUSE_SLAB = "A workbench or shelf is in the way at that height — slide it along the wall, or raise it.";
const SS_REFUSE_LOFT = "Lofts can't overlap — drop this one clear of the other.";

// ✅ THE 2026-09-04 GAP IS CLOSED (2026-09-09). It read: a wallOnly caller passes no `cand`, so
// its candidate band defaults to full height and a RAISED door — or a transom — is refused
// above a workbench or a low shelf, which is a legal arrangement. Carolyn hit it from the
// other side on 09-07: "there are times when if a window fits above a workbench, that it can
// be placed. Okay, so we need to look at measurements so that it can be placed."
//
// Every wallOnly call site now passes the candidate it was ALREADY building for
// checkDoorCollision, and ssCandBandIn below falls back to ssItemVBand for a non-slab. So a
// 2'x1' transom over a bench places, and a full-height door across one is still refused. The
// two directions finally agree, which is what this function's header has wanted since it was
// written.
//
// ⚠️ ssItemVBand speaks FEET; ssSlabBand speaks INCHES. Mixing them makes every opening twelve
// times too tall, which does not read as a unit bug — it reads as "nothing can be placed
// anywhere". Convert at this boundary, the only place that knows both units.
//
// ⚠️ A null band still means ASSUME CLASH, never "no overlap". An item that states no height is
// exactly the case where guessing is unsafe, so it keeps the old full-height blocker.
// `wallHeightFt` is optional and reaches only a vent's band (see checkDoorCollision's note).
function ssCandBandIn(cand, itemTypes, wallHeightFt) {
  if (!cand) return [0, 1e4];
  const slab = ssSlabBand(cand, itemTypes);
  if (slab) return slab;
  const cfg = itemTypes && itemTypes[cand.type];
  const v = cfg ? ssItemVBand(cand, cfg, itemTypes, wallHeightFt) : null;
  if (!v || !isFinite(v.bottomFt) || !isFinite(v.topFt)) return [0, 1e4];
  return [v.bottomFt * 12, v.topFt * 12];
}
// A vent placed IN THE GABLE (ventZone, 2026-09-15 — see ssVentSpan). Written out rather than
// through isVentItem because this sits inside the slab block, which the stub tests lift on its
// own; checkDoorCollision and wallSlabBlocker both call it.
function ssIsGableVent(it) { return !!(it && it.isVent && it.ventZone === "gable"); }
function wallSlabBlocker(sn, widthFtPx, existing, itemTypes, sc, cand, wallHeightFt) {
  if (!sn.wall) return null;
  // A vent in the gable is above the plate, and no workbench or shelf reaches past it.
  if (ssIsGableVent(cand)) return null;
  const candBand = ssCandBandIn(cand, itemTypes, wallHeightFt);
  const isH = sn.wall === "north" || sn.wall === "south";
  const candPos = isH ? sn.x : sn.y;
  const candHalf = widthFtPx / 2;
  for (const ob of existing) {
    if (ob.wall !== sn.wall || !ssSlabModel(ob.type, itemTypes)) continue;
    if (!ssBandsOverlap(candBand, ssSlabBand(ob, itemTypes))) continue;
    const obHalf = ((ob.widthFt || (itemTypes[ob.type] && itemTypes[ob.type].width)) * sc) / 2;
    const obPos = isH ? ob.x : ob.y;
    if (Math.abs(candPos - obPos) < candHalf + obHalf - 2) return ob;
  }
  return null;
}
function checkWallSlabOverlap(sn, widthFtPx, existing, itemTypes, sc, cand, wallHeightFt) {
  return !!wallSlabBlocker(sn, widthFtPx, existing, itemTypes, sc, cand, wallHeightFt);
}

// SAY WHICH THING IS IN THE WAY. Every click-to-place refusal used to read "A workbench is on
// that wall" whatever had actually blocked it, so a single shelf and a double shelf both
// reported a workbench that was nowhere on the plan — and the reader's next move is to go
// looking for it. Only the drag paths got this right, via SS_REFUSE_SLAB's "workbench or
// shelf", which is honest but still does not say WHICH.
//
// The name comes from the tenant's own catalog label, so it matches the button they placed it
// with. Labels are tenant-editable, so an odd one ("Shelving") produces slightly odd grammar
// — that is a fair trade against confidently naming the wrong object, and the fallback is the
// neutral "Something" rather than a guess.
//
// Re-walks the obstacle list rather than threading a value out of the check above: it runs
// only on the refusal path, over a handful of items, and it keeps all eight call sites to a
// one-line change with no new binding in a function body that already has many.
function ssSlabInWay(sn, widthFtPx, existing, itemTypes, sc, cand, tail) {
  const ob = wallSlabBlocker(sn, widthFtPx, existing, itemTypes, sc, cand);
  const c = ob && itemTypes && itemTypes[ob.type];
  const name = String((c && (c.label || c.shortLabel)) || "").trim();
  return (name ? "A " + name.toLowerCase() : "Something") + " is on that wall — " + tail;
}

function parseSize(s) {
  if (!s) return null;
  const m = s.match(/(\d+)\s*[x×✕]\s*(\d+)/i); // accept Unicode ×/✕ size labels too, not just ASCII x — else the building silently stays at the default size (audit #F2)
  return m ? { w: parseInt(m[1]), h: parseInt(m[2]) } : null;
}

// Check if a loft (edges in ft) has both ends of at least one axis attached to walls or other lofts
function checkLoftAttached(l, r, t, b, bldgW, bldgH, otherLoftEdges) {
  const tol = 0.3;
  const atWall = (val, wallVal) => Math.abs(val - wallVal) < tol;
  const touchesLoft = (edge, oKey, pMin, pMax, opMin, opMax) =>
    otherLoftEdges.some((o) => Math.abs(edge - o[oKey]) < tol && pMin < o[opMax] - tol && pMax > o[opMin] + tol);

  const leftOk = atWall(l, 0) || touchesLoft(l, "r", t, b, "t", "b");
  const rightOk = atWall(r, bldgW) || touchesLoft(r, "l", t, b, "t", "b");
  if (leftOk && rightOk) return true;

  const topOk = atWall(t, 0) || touchesLoft(t, "b", l, r, "l", "r");
  const bottomOk = atWall(b, bldgH) || touchesLoft(b, "t", l, r, "l", "r");
  if (topOk && bottomOk) return true;

  return false;
}

// ─── Page geometry, as a pure function of the building size ───────────────────
// The component derives scale/mgX/mgY from bldgW/bldgH on every render. Reflowing
// a layout after a size change needs the SAME derivation for the OLD size, to turn
// stored page-pixels back into feet — so the formula lives here, called twice
// (old, new), instead of being inlined once in the render body.
const SS_PAGE = { W: 850, H: 1100, TEXT_AREA_H: 340, TOP_LABEL_PAD: 30, BOT_LABEL_PAD: 30, RAMP_SPACE_FT: 2 };
// Narrowest canvas ROW that can carry the plan and the docked 3D panel side by side:
// plan floor 560 + gap 12 + panel floor 320 + row padding 40 = 932, rounded to 960.
// Measured on the ROW, never on window.innerWidth: the portal sidebar is 240px and
// collapses to 68px at max-width:900px, so the designer host is ~661px at a 901px
// viewport but ~832px at 900px — a viewport threshold would switch the dock ON for
// the narrower layout and OFF for the wider one.
const SS_DOCK_MIN_ROW_W = 960;
// THE EMBED CONTRACT. `?open3d=1` on a public designer link asks for the 3D panel to be
// docked beside the plan on arrival, instead of waiting behind the toolbar button.
//
// REDUNDANT SINCE 2026-09-12 (Carolyn: "3D View should always load automatically") — the
// panel now docks on arrival on every surface that can dock, param or not. Kept because the
// Settings embed snippet still emits it and an old link must not start reading as an error.
//
// It exists for the iframe snippet in Settings (Carolyn 2026-09-03, about a builder whose
// site is built on ShedPro): "I like this where they can see it. But the 3d needs to be
// open." Ahsan on the same call: "in the iframe code, we can prioritize 3D."
//
// A QUERY PARAM RATHER THAN A CONFIG FLAG, deliberately: the same tenant hands the plain
// link to some customers and the embed to others, so this is a property of the embed, not
// of the builder. Anything other than the literal "1" reads as off.
function ssOpen3DRequested() {
  if (typeof window === "undefined") return false;
  try { return new URLSearchParams(window.location.search).get("open3d") === "1"; } catch (e) { return false; }
}
// Settings -> Designer -> 3D docks the same panel beside a FORM, not beside a building plan,
// and a form needs less room to stay usable: the calibration grids are
// repeat(auto-fit, minmax(150px,1fr)) and still give two columns at ~390px, whereas the plan
// SVG has a real drawing to keep legible. 960 would refuse to dock on a 1280px window (the
// Settings row measures ~954 there), which is most of the laptops a style gets calibrated on.
const SS_DOCK_MIN_CAL_W = 760;
function pageGeom(bldgW, bldgH) {
  const visibleH = SS_PAGE.H - SS_PAGE.TEXT_AREA_H;
  const scale = Math.min(
    (SS_PAGE.W * 0.70) / bldgW,
    (visibleH * 0.70) / bldgH,
    (visibleH - SS_PAGE.TOP_LABEL_PAD - SS_PAGE.BOT_LABEL_PAD) / (bldgH + 2 * SS_PAGE.RAMP_SPACE_FT)
  );
  const pW = bldgW * scale, pH = bldgH * scale;
  return { scale, pW, pH, mgX: (SS_PAGE.W - pW) / 2, mgY: SS_PAGE.RAMP_SPACE_FT * scale + SS_PAGE.TOP_LABEL_PAD };
}

// Where a ramp sits for a given door position — the ramp is derived, never placed.
// Uses the ramp's OWN depth (heightFt) rather than the 2 ft default, so a catalog
// ramp with a longer run stays where it was drawn.
function rampPosFor(rmp, sn, g) {
  const depthPx = ((rmp && rmp.heightFt) || SS_PAGE.RAMP_SPACE_FT) * g.scale;
  if (sn.wall === "north") return { x: sn.x, y: g.mgY - depthPx / 2, rotation: 0, wall: "north" };
  if (sn.wall === "south") return { x: sn.x, y: g.mgY + g.pH + depthPx / 2, rotation: 0, wall: "south" };
  if (sn.wall === "west") return { x: g.mgX - depthPx / 2, y: sn.y, rotation: 90, wall: "west" };
  if (sn.wall === "east") return { x: g.mgX + g.pW + depthPx / 2, y: sn.y, rotation: 90, wall: "east" };
  return null;
}

// Items the customer sizes themselves, so shrinking one to fit a smaller building
// preserves their intent. A DOOR is not in this list on purpose: a 6 ft double door
// quietly becoming 4 ft would change what they are buying.
// Rough openings split into a DOOR ro and a WINDOW ro (2026-09-08, migration 224). The generic
// `roughOpening` is RENDER-ONLY from here on: LEGACY_LAYOUT_FALLBACK keeps it drawing on the
// designs that already carry one, and every branch below accepts all three keys so an old design
// behaves exactly as it always did. The key is NEVER renamed — 171_interior_shelves.sql:44 states
// the rule: item_key is the join to every layout_item_pricing row and to the `type` string on
// every saved design.
const SS_RO_KEYS = ["roughOpening", "roughOpeningDoor", "roughOpeningWindow"];
function ssIsRO(t) { return t === "roughOpening" || t === "roughOpeningDoor" || t === "roughOpeningWindow"; }
// The window RO is the only one that sits off the floor. The legacy key stays door-shaped, which
// is what it has always been in 3D (D3.RO_H === D3.DOOR_H, sill 0).
function ssIsWindowRO(t) { return t === "roughOpeningWindow"; }
// Plan/PDF label: RO-D1 / RO-W1 for the two new kinds, bare RO-1 for legacy items so old plans
// re-export identically. Numbering is PER KIND and positional, like the single counter it
// replaces — recomputed at render time, never stored.
function ssRoPrefix(t) { return t === "roughOpeningDoor" ? "RO-D" : t === "roughOpeningWindow" ? "RO-W" : "RO-"; }
function ssRoLabel(item, items) {
  const idx = items.filter((i) => i.type === item.type).findIndex((r) => r.id === item.id);
  return ssRoPrefix(item.type) + (idx + 1);
}

const SS_SHRINKABLE = { workbench: true, roughOpening: true, roughOpeningDoor: true, roughOpeningWindow: true, loft: true, shelf: true, doubleShelf: true };
// Palette sections, in display order. The KEY is what `layout_item_types.palette_group`
// stores; an item with no group (every tenant config until it is regenerated) renders in the
// unlabelled tail, which is what keeps the grouped palette safe to ship ahead of the data.
const PALETTE_GROUP_LABEL = { doors: "Doors", windows: "Windows", interior: "Interior", electrical: "Electrical" };
const PALETTE_GROUP_ORDER = ["doors", "windows", "interior", "electrical"];
const SS_WALL_ORDER = { north: ["south", "east", "west"], south: ["north", "east", "west"], east: ["west", "north", "south"], west: ["east", "north", "south"] };

/**
 * Move every placed item into the equivalent legal position for a new building size.
 *
 * PURE — returns { items, events } and mutates nothing, so the caller can inspect the
 * events and decide whether to commit. That is what makes "revert the size change when
 * something cannot be placed" possible without ever leaving a half-reflowed layout.
 *
 * events: { id, type, label, kind } where kind is "movedWall" | "resized" | "blocked".
 * Sliding along the SAME wall is deliberately not an event — it is what the customer
 * expects when a building grows or shrinks, and reporting it would bury the two things
 * they do need to know.
 */
//
// `gablePlace(cand, sn, geom)` is optional, passed by the SIZE change and, at unchanged dimensions,
// by a STYLE change (ssRefitGableVents): the patch that puts
// a gable vent (ssIsGableVent) into the gable above `sn.wall` on the NEW building, or null. A null
// clears the zone, so a vent whose gable the new size took away (a landscape footprint's ends are
// west/east) or made too small comes back down to the wall rather than being drawn in mid-air.
// repairLoaded passes nothing, and then a gable vent keeps its zone exactly as saved.
function reflowItems(items, prev, next, ITEMS, gablePlace) {
  const A = pageGeom(prev.w, prev.h), B = pageGeom(next.w, next.h);
  const events = [];
  const byId = new Map();
  const placed = [];                       // already-reflowed items, for collision tests
  const labelOf = (it) => (ITEMS[it.type] && ITEMS[it.type].label) || it.type;

  // Try to seat a wall item at `wantFt` along `wall`, sliding to the nearest clear spot.
  // Returns the snap result, or null when the wall has no room.
  const seat = (it, cfg, wall, wantFt, wFt, hFt) => {
    const isH = wall === "north" || wall === "south";
    const wallLen = isH ? next.w : next.h;
    const half = wFt / 2;
    if (wFt > wallLen) return null;
    const lo = half, hi = wallLen - half;
    const start = Math.max(lo, Math.min(wantFt, hi));
    // Search outward from the wanted spot in 0.25 ft steps, nearest first.
    for (let d = 0; d <= (hi - lo) + 0.25; d += 0.25) {
      for (const c of (d === 0 ? [start] : [start - d, start + d])) {
        if (c < lo - 0.001 || c > hi + 0.001) continue;
        const px = (isH ? B.mgX : B.mgY) + c * B.scale;
        const sn = cfg.wallSnap
          ? snapToWallInterior(wall, isH ? px : B.mgX, isH ? B.mgY : px, wFt * B.scale, hFt * B.scale, B.pW, B.pH, B.mgX, B.mgY)
          : snapToWall(wall, isH ? px : B.mgX, isH ? B.mgY : px, wFt * B.scale, hFt * B.scale, B.pW, B.pH, B.mgX, B.mgY);
        let cand = { ...it, ...sn, widthFt: wFt, heightFt: hFt };
        let out = sn;
        if (gablePlace && ssIsGableVent(it)) {
          const g = gablePlace(cand, sn, B);
          out = g || { ...sn, ventZone: null, ventRiseFt: null };
          cand = { ...cand, ...out };
        }
        if (checkDoorCollision(cand, { ...cfg, width: wFt }, placed, ITEMS, B.scale)) continue;
        if (checkWallSlabOverlap(out, wFt * B.scale, placed, ITEMS, B.scale, cand)) continue;
        return out;
      }
    }
    return null;
  };

  // ── Pass 1: everything except ramps (which are derived from their door) ──
  for (const it of items) {
    const cfg = ITEMS[it.type];
    // Annotations live in PAGE space, deliberately independent of the building —
    // moving them with the plan would be a regression, not a completion.
    if (!cfg || cfg.lineType || it.type === "textNote" || it.type === "line") { byId.set(it.id, it); continue; }
    if (cfg.doorSnap) continue;            // pass 2

    const isWall = (cfg.wallOnly || cfg.wallSnap) && it.wall;
    if (isWall) {
      const isH = it.wall === "north" || it.wall === "south";
      const wantFt = isH ? (it.x - A.mgX) / A.scale : (it.y - A.mgY) / A.scale;
      const hFt = it.heightFt || cfg.height;
      let wFt = it.widthFt || cfg.width;
      const wallLen = isH ? next.w : next.h;
      if (wFt > wallLen && SS_SHRINKABLE[it.type]) {
        const shrunk = Math.max(ssIsRO(it.type) ? 0.5 : 2, wallLen);
        if (shrunk !== wFt) { wFt = shrunk; events.push({ id: it.id, type: it.type, label: labelOf(it), kind: "resized", to: wFt }); }
      }
      let sn = seat(it, cfg, it.wall, wantFt, wFt, hFt);
      let movedWall = false;
      if (!sn) {
        for (const w2 of (SS_WALL_ORDER[it.wall] || [])) {
          const isH2 = w2 === "north" || w2 === "south";
          sn = seat(it, cfg, w2, (isH2 ? next.w : next.h) / 2, wFt, hFt);
          if (sn) { movedWall = true; break; }
        }
      }
      if (!sn) { events.push({ id: it.id, type: it.type, label: labelOf(it), kind: "blocked" }); byId.set(it.id, it); continue; }
      if (movedWall) events.push({ id: it.id, type: it.type, label: labelOf(it), kind: "movedWall", to: sn.wall });
      const nit = { ...it, ...sn, widthFt: wFt };
      byId.set(it.id, nit); placed.push(nit);
      continue;
    }

    if (it.type === "loft") {
      let wFt = it.widthFt || cfg.width, hFt = it.heightFt || cfg.height;
      let cxFt = (it.x - A.mgX) / A.scale, cyFt = (it.y - A.mgY) / A.scale;
      // A loft placed by clicking is seeded widthFt = bldgW (a snapshot of the building
      // width). If it spanned wall to wall, it should still span wall to wall.
      if (Math.abs(wFt - prev.w) < 0.35) { wFt = next.w; cxFt = next.w / 2; }
      else cxFt = cxFt * (next.w / prev.w);
      cyFt = cyFt * (next.h / prev.h);
      const wasW = wFt, wasH = hFt;
      wFt = Math.max(2, Math.min(wFt, next.w));
      hFt = Math.max(2, Math.min(hFt, next.h));
      if (wFt > next.w || hFt > next.h) { events.push({ id: it.id, type: it.type, label: labelOf(it), kind: "blocked" }); byId.set(it.id, it); continue; }
      if (wFt !== wasW || hFt !== wasH) events.push({ id: it.id, type: it.type, label: labelOf(it), kind: "resized", to: wFt });
      cxFt = Math.max(wFt / 2, Math.min(cxFt, next.w - wFt / 2));
      cyFt = Math.max(hFt / 2, Math.min(cyFt, next.h - hFt / 2));
      const nit = { ...it, x: B.mgX + cxFt * B.scale, y: B.mgY + cyFt * B.scale, widthFt: wFt, heightFt: hFt };
      byId.set(it.id, nit); placed.push(nit);
      continue;
    }

    // Free-floating: keep it inside the new box.
    const wFt = it.widthFt || cfg.width, hFt = it.heightFt || cfg.height;
    let cxFt = ((it.x - A.mgX) / A.scale) * (next.w / prev.w);
    let cyFt = ((it.y - A.mgY) / A.scale) * (next.h / prev.h);
    cxFt = Math.max(wFt / 2, Math.min(cxFt, next.w - wFt / 2));
    cyFt = Math.max(hFt / 2, Math.min(cyFt, next.h - hFt / 2));
    const nit = { ...it, x: B.mgX + cxFt * B.scale, y: B.mgY + cyFt * B.scale };
    byId.set(it.id, nit); placed.push(nit);
  }

  // ── Pass 2: ramps follow their door, or go with it ──
  for (const it of items) {
    const cfg = ITEMS[it.type];
    if (!cfg || !cfg.doorSnap) continue;
    const door = byId.get(it.snapDoorId);
    const pos = door && door.wall ? rampPosFor(it, door, B) : null;
    if (!pos) continue;                    // orphaned ramp is dropped, as when its door is deleted
    byId.set(it.id, { ...it, ...pos });
  }

  return { items: items.map((it) => byId.get(it.id)).filter(Boolean), events };
}

// Point on a note box's border in the direction of a target — where the note's
// leader (pointer) line starts, so the dashed line begins at the pill's edge
// instead of its center. If the target is inside the box, returns the target
// itself (degenerate line; callers skip drawing when start ≈ end).
function noteEdgePoint(cx, cy, w, h, tx, ty) {
  const dx = tx - cx, dy = ty - cy;
  if (!dx && !dy) return { x: cx, y: cy };
  const t = Math.min(
    dx ? (w / 2) / Math.abs(dx) : Infinity,
    dy ? (h / 2) / Math.abs(dy) : Infinity,
    1
  );
  return { x: cx + dx * t, y: cy + dy * t };
}

// Determine which positional wall (north/south/east/west) is the FRONT
// based on door placement. Double door wins over single door.
function getFrontWall(items) {
  // Catalog fixture doors count as doors too; a double-leaf (built-in doubleDoor, or a
  // fixture whose operation is "double") wins over a single, same as before.
  //
  // ⚠️ A RAISED DOOR DOES NOT VOTE (Carolyn's loft door, 2026-09-04 — see doorSillStamps).
  // This function is how a building learns which side is its FRONT, and every user-facing
  // wall label plus every front/back/left/right field in the submit payload keys off that.
  // A loft door hangs high on a GABLE END — the one wall a shed's front is never on — so
  // letting it vote would silently rotate the customer's building: the wall their walk door
  // is on stops being called FRONT and the estimate follows it. Nothing would look broken.
  //
  // A building whose ONLY door is a loft door therefore has no front, which is exactly the
  // answer a building with no doors at all already gets.
  const grounded = items.filter((i) => !ssDoorSillFt(i));
  const doubles = grounded.filter((i) => i.wall && (i.type === "doubleDoor" || (i.type === "fixtureDoor" && i.operation === "double")));
  if (doubles.length > 0) return doubles[0].wall;
  const singles = grounded.filter((i) => i.wall && (i.type === "singleDoor" || i.type === "fixtureDoor"));
  if (singles.length > 0) return singles[0].wall;
  return null;
}

// ── Fixtures catalog (Options → Doors) → placeable designer tools + rendering ──────
// Each active catalog door (from get_fixtures) becomes a palette tool keyed `fx:<id>`
// (wallOnly, carrying its own width in feet). Placing one creates a stable `fixtureDoor`
// item that SNAPSHOTS the door's spec (name/width/price/swing/operation) so a later catalog
// edit never changes a saved design. FIXTURE_DOOR_CFG is the render cfg for those placed
// items; `noPalette` keeps it out of the tool row (only the fx: tools are shown).
const FIXTURE_DOOR_COLOR = "#D97706";         // matches the built-in Single Door glyph
const FIXTURE_DOOR_COLOR_DOUBLE = "#B45309";  // matches the built-in Double Door glyph
// Amber like the built-in doors, darker for a double so it reads the same as doubleDoor.
function fixtureDoorColor(item) { return item && item.operation === "double" ? FIXTURE_DOOR_COLOR_DOUBLE : FIXTURE_DOOR_COLOR; }
const FIXTURE_DOOR_CFG = { label: "Door", color: FIXTURE_DOOR_COLOR, wallOnly: true, width: 3, height: 0.5, shortLabel: "DOOR", noPalette: true, isFixtureDoor: true };
// The single "Door" palette tool. Arming it and clicking a wall opens the door picker
// (below) instead of placing immediately — the shopper chooses WHICH door (and its swing/
// operation where more than one is offered) in the popup.
const DOOR_PICKER_CFG = { label: "Door", color: FIXTURE_DOOR_COLOR, wallOnly: true, width: 3, height: 0.5, shortLabel: "DOOR", isDoorPicker: true, group: "doors" };
// Custom ramps (custom mode). The "Ramp" tool attaches to a door (doorSnap) and opens the ramp
// picker. A placed custom ramp is a normal type:"ramp" item — so it reuses ALL the existing ramp
// machinery (render, door-snap follow, delete-cascade, z-order) — but carries the chosen style's
// own width/length + a priced snapshot (vs the simple built-in ramp which takes the door's width).
const FIXTURE_RAMP_COLOR = "#0284C7";
const RAMP_PICKER_CFG = { label: "Ramp", color: FIXTURE_RAMP_COLOR, icon: "⬛", doorSnap: true, width: 3, height: 2, shortLabel: "RAMP", isRampPicker: true, group: "doors" };
// Simple ramp — a fully self-contained option (render + placement), NO longer the built-in `ramp`
// layout item. Auto-widths to the door it attaches to (handled in handleClick's doorSnap branch,
// same as before). Stone color matches the old built-in so already-placed ramps look identical.
// ITEMS.ramp is ALWAYS this cfg (so every placed type:"ramp" renders), placeable only when the
// tenant offers a simple ramp (rampSettings.enabled + simple mode).
const SIMPLE_RAMP_CFG = { label: "Ramp", color: "#78716C", icon: "⬛", doorSnap: true, width: 3, height: 3, shortLabel: "RAMP", isSimpleRamp: true, group: "doors" };
// Catalog windows. The "Window" tool is wall-placed (like the door picker). A placed catalog
// window is a normal type:"window" item — so it reuses the built-in window's render (mullions,
// wall bar), collision, and payload — but carries the chosen style's width + a priced snapshot
// (built-in windows have no fixtureItemId; that's how the two are told apart in pricing).
const FIXTURE_WINDOW_COLOR = "#0EA5E9";
const WINDOW_PICKER_CFG = { label: "Window", color: FIXTURE_WINDOW_COLOR, icon: "🪟", wallOnly: true, width: 2, height: 0.5, shortLabel: "WIN", isWindowPicker: true, group: "windows" };
// Catalog VENTS (Carolyn 2026-09-04 @25:19-27:14). Asked whether a vent belonged with the
