    const pb = porchBuilt && isFinite(Number(porchBuilt.posts)) && isFinite(Number(porchBuilt.pitch)) ? porchBuilt : null;
    const in12 = (p) => `${Math.round(Number(p) * 120) / 10} in 12`;
